def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    strong_opp_count = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 4:
                strong_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opps:
        if hp <= 2 or no_water >= 1:
            return min(budget, 28.0)
        return min(budget, 12.0)

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units <= 1.05:
        scarcity = 2
    elif units <= 1.6:
        scarcity = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 2
    elif hp <= 4:
        danger += 1
    if no_water >= 2:
        danger += 2
    elif no_water >= 1:
        danger += 1

    if danger >= 4:
        bid = max(62.0, highest_prev + 4.0)
    elif danger >= 2:
        bid = max(44.0, avg_prev + 3.0, highest_prev * 0.72)
    else:
        if scarcity == 2:
            bid = max(34.0, avg_prev + 2.0)
        elif scarcity == 1:
            bid = max(24.0, avg_prev * 0.7)
        else:
            bid = 16.0

    if highest_prev >= 120.0 and danger == 0:
        bid = min(bid, 22.0)
    elif highest_prev >= 90.0 and danger <= 1:
        bid = min(bid, 28.0)

    if strong_opp_count >= 2 and scarcity >= 1 and danger >= 2:
        bid = max(bid, highest_prev + 1.5)

    if day >= 8 and hp >= 5 and no_water == 0 and scarcity == 0:
        bid = min(bid, 14.0)

    min_guard = 0.0
    if hp <= 2 or no_water >= 2:
        min_guard = 55.0
    elif hp <= 4 or no_water >= 1:
        min_guard = 36.0
    bid = max(bid, min_guard)

    if budget <= 0:
        return 0.0
    return max(0.0, min(float(budget), float(bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 10.0))

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 0.9))

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev < supply * 2:
            return float(min(my_status['budget'], max_prev + 2.0))

    return float(min(my_status['budget'], supply * 1.5))
